; now enter the function proper;; Begin by setting up our stack frame......	phd	tsc	sec	sbc #FrameSize	tcd	tcs		;; Now that our frame is set up, let's get to work...; MyOpenRec.openPathname:=@currentDirPath;		lda #CurrentDirPath>>16	sta >MyOpenRec+4	lda #CurrentDirPath	sta >MyOpenRec+2	lda #0	sta >MyOpenRec	; OpenPD(MyOpenRec);	_OpenPD MyOpenRec	bcc @1	cmp #$45	;VolNotFound?	bne @otherError	sta >Stopping@otherError	sta >AsmToolErr	brl EndProcLevel@1; MyRefNum:=MyOpenRec.Openrefnum;	lda >MyOpenRec	sta <MyRefNum; MyDirEntry.base:=1;; MyDirEntry.Displacement:=1;	lda #1	sta >MyDirEntry+4	sta >MyDirEntry+6; MyDirEntry.NameBuffer:=@tempNamePtr;	lda #TempNamePtr>>16	sta >MyDirEntry+$000A	lda #TempNamePtr	sta >MyDirEntry+$0008	; tempNamePtr.stat:=16;	lda #40	sta >TempNamePtr	Repeat; For proper asynch operation, we must now test the entrycount first, if we; have passed our threshold of entries then we need to back out for now...	lda >EntryCount	; get the current entry count	cmp #MaxPerLevel	; have we done the proper number yet?	blt @Repeatcont	brl AsynchExit	; else exit asynch level@RepeatCont; MyDirEntry.refnum:=MyRefNum;	lda <MyRefNum	sta >MyDirEntry;; Now we determine if we should stop now.	lda >Stopping	bne @BetterStop	; if the flag is non-zero then we must stop; Get_Dir_Entry(MyDirEntry);	_Get_Dir_Entry MyDirEntry	bcc @2	cmp #$45	; Volume Not Found?	bne @BetterStop	; no, exit normally	sta >Stopping	; else make sure we stop completely@BetterSTop	brl GDEError; if AsmToolErr=0 then;  begin;  tempString[0]:=char(tempNamePtr.length); {Set the length of the string}@2;; First bump the entry count to indicate we got a good one	lda >EntryCount	inc a	sta >EntryCount		lda >TempNamePtr+2	sep #$20	Longa Off	sta >tempString	rep #$20	Longa On	;   for i:=1 to 32 do;     tempString[i]:=tempNamePtr.theName[i];	ldx #0@CopyLoop1		lda >tempNamePtr+4,x	sta >tempString+1,x	inx	inx	cpx #32	; see if we are finished...	blt @CopyLoop1	;    AddFile(tempString);	{Add the filename to the list...}	PushLong #tempString	jsl AsmAddFile	pla	pla	;    if MyDirEntry.fileType = $000F then  {Check for recursion...};      begin	lda >MyDirEntry+$000E	cmp #$000F	beq @3	brl NotADirectory			    ;        MyPathLevel:=ord(CurrentDirPath[0]);	{Save the old pathname}@3	lda >CurrentDirPath	and #$00FF	sta <MyPathLevel		;        if MyPathLevel+tempNamePtr.length<255 then	clc	adc >tempNamePtr+2	cmp #$0100	blt @4	brl fNameTooLong;;         begin;           currentDirPath:=Concat(currentDirPath,tempString,':');@4	lda #currentDirPath>>16 ; create a pointer to our dest string	sta <tempDeref+2	lda #currentDirPath	sta <tempDeref	lda >currentDirPath	    ; add its current length...	and #$00FF	sec	   ;always add 1 extra	adc <tempderef	sta <tempDeref	bcc @5	inc <tempDeref+2@5	lda >tempNamePtr+2	    ; get the length to copy	sta <i	    ; save it on direct page		ldx #0	; now do our copy...@concatLoop	lda >tempNamePtr+4,x    ; source word	txy	sta [<tempderef],y	; save it in our destination	inx	inx	cpx <i	; are we done?	blt @concatLoop	; nope, keep going...; we are now done copying the string, now fix the length and add the : at the end	lda >currentDirPath	clc	adc <i	inc a	; add 1 for the ":"	sta >currentDirPath	and #$00FF	; just get the length	tax	; use as an index	lda #':'	; load the terminator char	sta >currentDirPath,x    ; and finish the name	;           ProcessLevel;	pha	; room for result	pea $FFFF	; flag says we are reentering	jsl ProcessLevel	; do the next level...	pla; AsmToolErr:=0;	;          CurrentDirPath[0]:=chr(MyPathLevel);	{Back the sucker off now...}	lda <MyPathLevel	sep #$20	longa Off	sta >CurrentDirPath	rep #$20	LongA On	;         end;;        end;;       end;fNameTooLongNotADirectory	brl Repeat;; Interupt ready...AsynchExit	phd	; save the current direct page also!	tsc	; get the current stack level	sta >StackLevel	; and save it in our global		lda >PascalStack	; get the DA stack level back	tcs	; and make it the current stack	lda >PascalDPage	tcd	lda #1	; get the proper level flag	sta spudResult,s	; and make it the result for now...	lda spudRTL+1,s	; move the RTL down	sta spudRTL+3,s	; down 2 bytes	lda spudRTL,s	sta spudRTL+2,s	pla	; recover the crap	RTL	; and finally returnGDEError;   until AsmToolErr<>0;;   debug;; MyClose.fileRefNum:=MyRefNum;; ClosePD(MyClose);	lda <MyRefNum	sta >MyClose	_ClosePD MyClose	; end; {procedure}EndProcLevelProcessError1	tdc	; unlink our local frame	clc	adc #FrameSize	tcs	; make it our current stack	pld	; recover the orihginal dpage;; Now we need to unlink the rest of the alternate stack crap; and also see where we were called from...	pla	; recover the old stack level	bne @proce1	; if this is non-zero then we are recursed	lda >PascalDPage	; recover the direct page	tcd	lda >PascalStack	; if zero, get the pascal stack level@ProcE1	tcs	; make it the current stack pointer	lda spudFlag,s	; get the spudflag	sta spudResult,s	; and make it the result for now...	lda spudRTL+1,s	; move the RTL down	sta spudRTL+3,s	; down 2 bytes	lda spudRTL,s	sta spudRTL+2,s	pla	; recover the crap	RTL	; and finally return	PascalDPage	ds.W 1	; place to save the pascal direct page	EndP;; The following will do the proper comparison and then add the item to the list if; it matches the proper criterion;AsmAddFile	Proc Export	with PopupGlobals	import InvisibleFlag	; Stack for this call...tempDeref	equ 1tempHandle	equ tempDeref+4InputString	equ tempHandle+4i	equ InputString+4OldDPage	equ i+2theRTL	equ OldDPage+2theName	equ theRTL+3FrameSize	equ theRTL;;DirEntryRec = RECORD;DERrefNum 	equ 0	; integerDERreserved 	equ DERRefNum+2	; integerDERbase 	equ DERreserved+2	; Integer;DERdisplacement 	equ DERbase+2	; Integer;DERnameBuffer 	equ DERdisplacement+2 ; Ptr;DERentryNum 	equ DERnameBuffer+4	; Integer;DERfileType 	equ DERentryNum+2	; Integer;DERendOfFile 	equ DERfileType+2	; Longint;DERblockCount 	equ DERendOfFile+4	; Longint;DERcreateTime 	equ DERblockCount+4	; TimeRec;DERmodTime 	equ DERcreateTime+8	; TimeRec;DERaccess 	equ DERmodTime+8	; Integer;DERauxType 	equ DERaccess+2	; Longint;DERfileSysID 	equ DERauxType+4	; Integer;;; Begin by setting up our stack frame......;	lda 4,s	tax	lda 6,s	tay	; recover our parameter		phd	tsc	sec	sbc #FrameSize	tcd	tcs		stx <InputString	sty <InputString+2*** added 1-Oct-91 DAL -- only find invisible files if we want them	lda >MyDirEntry+DERaccess	and #$0004	;invisible bit	beq @notInvisible	lda >InvisibleFlag	and #$00ff	bne @findItAnyway	brl EndProcLevel@findItAnyway@notInvisible*** end 1-Oct-91; Now do the proper match	jsr MatchIt	bcc @addIt	brl EndProcLevel@addit	lda >MyListCnt	; see if we have too many items	cmp #MaxEntries	; see if we are beyond the threshold	blt @Addit010	; if not, then continue	lda #$FFFF	; flag list overrun	sta >Stopping	; and save it in our flag to say stop	brl EndProcLevel@Addit010; tempHandle:=Str255Hndl(NewHandle(16,MyID+$0700,attrFixed,NIL));	pha	; room for result	pha	pea 0	; size	pea 40	; 32 bytes	lda >MyID	ora #$0700	pha	pea $4000	pha	pha	_NewHandle	pla	plx	sta <tempHandle	stx <tempHandle+2	; PtrToHand(@theFile,Handle(tempHandle),16);	{copy the file name...}	pei <InputString+2	pei <InputString	pei <tempHandle+2	pei <tempHandle	PushLong #40	_PtrToHand	; MyList^^[myListCnt].memString:=Ptr(tempHandle^); {save the string pointer}	lda >MyList	; deref MyList	sta <tempDeref	lda >MyList+2	sta <tempDeref+2	ldy #2	lda [<tempDeref],y	tax	lda [<tempDeref]	sta <tempDeref	stx <tempDeref+2; now create a pointer to the proper record in the list...; each list entry is 20	lda >MyListCnt	; create MyListCnt*10	asl a	pha	asl a	asl a	clc	adc 1,s	plx	asl a	; multiply by 2 to get *20	clc	adc <tempDeref	; add the low byte first	tax	; and save it...	ldy #2	; now the high byte	lda <tempDeref+2	bcc @2	inc a@2	sta <tempDeref+2	stx <tempDeref;; Lucky for us all the proper file info is in the current dir entry record; still. So suck some more info out of the dir entry and put them into my record; here...;memFlag	equ 4memFullName	equ 6memFileType	equ 10memAuxType	equ 12memEOF	equ 16;; we now have a pointer to the list element let's stuff it ; First the string pointer	ldy #2	lda [<tempHandle],y	sta [<tempDeref],y	lda [<tempHandle]	sta [<tempDeref]	; MyList^^[myListCnt].memFlag:=0;	{set to member type}	lda #0	ldy #4	sta [<tempDeref],y;; And now, update the rest of the files data to reflect the dir entry data	lda >MyDirEntry+DERAuxType	ldy #memAuxType	sta [tempDeref],y	lda >MyDirEntry+DERAuxType+2	ldy #memAuxType+2	sta [tempDeref],y	lda >MyDirEntry+DERfileType	ldy #memfileType	sta [tempDeref],y	lda >MyDirEntry+DERendOfFile	ldy #memEOF	sta [tempDeref],y	lda >MyDirEntry+DERendOfFile+2	ldy #memEOF+2	sta [tempDeref],y;; Now that the record is updated, update the list ; tempHandle:=Str255Hndl(NewHandle(ord(theFile[0])+ord(CurrentDirPath[0])+3,MyID+$0700,0,NIL));	lda [<InputString]	clc	adc >CurrentDirPath	and #$00FF	adc #3		pha	pha		pea 0	pha	lda >MyID	ora #$0700	pha	pea 0	pha	pha	_NewHandle;  MyList^^[myListCnt].MemFullName:=newHandle;	ldy #6	pla	sta [<tempDeref],y	sta <tempHandle	iny	iny	pla	sta [<tempDeref],y	sta <tempHandle+2	; tempHandle^^:=Concat(currentDirPath,tempString);	ldy #2	lda [<tempHandle],y	sta <tempderef+2	lda [<tempHandle]	sta <tempDeref; First, copy current path over	lda >currentDirPath	and #$00FF	sta <i	; set the length to copy		ldy #1	ldx #1; and start the copy@copyCur	lda >currentDirPath,x	sta [<tempderef],y	iny	inx	cpx <i	blt @copyCur	; now copy input string to the end...	lda <i	clc	adc <tempDeref	sta <tempderef	bcc @10	inc <tempDEREF+2@10	; compute