	; get the length of the match string	sta <i	cmp [<InputString]	blt @Cont	beq @Cont	brl MatchFail@cont	ldy #1@CompLoop	tyx	; make both indexs the same	lda [<InputString],y		cmp #'A'	; first see if its upper case	blt @NonAlpha	; if less than its a non-alpha compare	ora #$20	; make it lower case always...	sta <matchTemp	; save it for a second	lda >MatchStr,x	; get the char to match	ora #$20	; make sure its lower case	cmp <matchTemp	; see if they are the same	beq @NextChar	brl MatchFail	@NonAlpha	cmp >MatchStr,x	beq @NextChar	brl MatchFail@NextChar	iny	cpy <i	; test if we are done...	blt @compLoop	beq @compLoop	REP #$20	Longa On	clc	rts	EndsWith; Test to see if the filename is an exact match of the matchstr	sep #$20	Longa Off	lda >MatchStr	; get the length of the match string	sta <i	cmp [<InputString]	blt @Cont	beq @Cont	brl MatchFail@cont		; now set up the counters for matching	lda [<inputString]	; get the length of the source str	tay	; place it in <X>	lda <i	; now get the length of the match string	tax	@CompLoop			lda >MatchStr,x	; get the last char of match string		cmp #'A'	; first see if its upper case	blt @NonAlpha	; if less than its a non-alpha compare	ora #$20	; make it lower case always...	sta <matchTemp	; save it for a second	lda [<inputString],y ; get the char to match	ora #$20	; make sure its lower case	cmp <matchTemp	; see if they are the same	beq @NextChar	brl MatchFail	@NonAlpha	cmp [<InputString],y	beq @NextChar	brl MatchFail@NextChar	dey	; decrement input counter	dex	; and match counter	bne @CompLoop	; if MatchCounter >0 then keep going	REP #$20	Longa On	clc	; else we are done and we found a match	rts	;Contains; Now see if input contains matchString; First be sure that the Matchstr can be contained by testing the length; NOTE: This routine requires that the matchstr be lowercased first.;; This routine trashes i and matchtemp;	stz i	stz MatchTemp	stz MatchTemp+2	sep #$20	Longa Off	lda >MatchStr	; get the length of the match string	sta <i	; into i (our counter)	cmp [<InputString]	blt @Cont	beq @Cont	brl MatchFail;; at this point we know that it is physically possible for matchstr to fit inside; the inputstring. Now, start testing for the match...; MatchTemp will contain our current pointer... matchTemp+2 the size of Inputstr;@cont		rep #$20	longa On	lda [<InputString]	and #$00FF	sta <MatchTemp+2	ldy #0	; init our string pointer@FindFirst	cpy <MatchTemp+2	; see if we are done	bge @NotHere	; if so, it must not be here!	iny	lda [<InputString],y	and #$00FF	; strip the byte...	cmp #'A'	; lowercase it...	blt @FF0010	cmp #'Z'+1	bge @FF0010	ora #$0020@FF0010	sta <MatchTemp	lda >MatchStr+1	and #$00FF	cmp <MatchTemp	; see if these are the same...	bne @FindFirst	; they are not, so continue till done	;; If we get here then we have found the first char of matchstr in inputstr; let's continue on...;; Save current value for Y first	sty <MatchTemp	; see if whats left of the input string can contain match string	lda <MatchTemp+2	; length of inputstr	sec	sbc <MatchTemp	; see if its too long...;; 2/12/90	Mensch; Fix bug here since Y was already incremented (Its based on 1 not 0) the following; arithmetic will not work right. what we really have to do now is decrement it...;	inc a	; adjust for a too big Y	cmp <i	bge @maybehere	; if its >= than i then it cound be here!@NotHere; otherwise, it can't be in this string... better button up and leave	rep #$20	longa on	sec	; signal failure	rts	; and go back...	@MaybeHere; This routine will determine if the string is actually inside of the input; string...	ldy <MatchTemp	; start at the beginning	phy	; save the length...	ldx #0	; with both strings...@FindRest	cpx <i	; is x equal to the ending condition?	beq @GotIt	; if so, then I got one!	inx	lda [<InputString],y	and #$00FF	; strip the byte...	cmp #'A'	; lowercase it...	blt @FR0010	cmp #'Z'+1	bge @FR0010	ora #$0020@FR0010	sta <MatchTemp	lda >MatchStr,x	and #$00FF	cmp <MatchTemp	; see if these are the same...	bne @tryAgain	; they are not, so back to main loop	iny	bra @FindRest@TryAgain	ply	; if we get here the string wasn't found yet	brl @FindFirst;; This is called when we have found the whole string ...@GotIt	ply	; recover its location...	rep #$20	longa on	clc	; signal success	rts	; and go back...	MatchFail	rep #$20	longa on	sec	; signal failure	rts	; and go back...		************************************************************** WildCard* * This routine searches InputString for MatchStr and returns with* the carry clear if found, set if not found...* * The current wild card operation is the same as Equal except that* it also supports the following Wildcard characters:**  §- Match any ASCII letter (Upper or lower case)*  £- Match any numeric digit*  Å- Match any stream of data (Only one of these per find item)*************************************************************WildCard; Test to see if the filename is an exact match of the matchstr	stz i	stz MatchTemp+2	sep #$20	Longa Off	lda >MatchStr	; get the length of the match string	sta MatchTemp+2	; save it in our special place	lda [<InputString]	; now do the input string length	sta <i; Note no length checking here because of wild card construction...@cont	ldy #1	ldx #1@CompLoop		; make both indexs the same	lda >MatchStr,x	; get the next char to match	cmp #'£'	; is it match number?	beq @CompNum		cmp #'§'	; is it match Letter?	beq @CompAlpha	cmp #'Å'	; is it stream of data?	beq @CompHole; Else just a normal compare will do...	lda [<InputString],y		cmp #'A'	; first see if its upper case	blt @CompNorm01	; if less than its a non-alpha compare	cmp #'Z'+1	; is it greater?	bge @CompNorm01	ora #$20	; make it lower case always...@CompNorm01	cmp >MatchStr,x	; get the char to match	beq @NextChar	brl @MatchFail;; Only test its numericness....@CompNum	lda [<InputString],y	cmp #'0'	blt @MatchFail	cmp #'9'+1	bge @MatchFail	bra @NextChar	;; Test its alphaness...@CompAlpha	lda [<InputString],y	cmp #'A'	blt @MatchFail	cmp #'Z'+1	blt @NextChar	cmp #'a'	blt @MatchFail	cmp #'z'+1	blt @NextChar@MatchFail	brl MatchFail;; The match passes so far..@NextChar	iny	inx		cpx <MatchTemp+2	; see if we are finished..	blt @ContHC	beq @ContHC	bra @MatchGood	; else if size does not pan out then its a fail..@ContHC	cpy <i	; test if we are done...	blt @compLoop	beq @compLoop@MatchGood	REP #$20	Longa On	clc	rts	;; This next routine will work with holes. If a whole has been found then it; will finish finding the rest of the string starting at the back...; NOTE:<X> contains the offset into the matchstr;      <Y> comtains the offset into the inputstring;@CompHole; First see if wild card is at the end of the match string. If so then ; we have found a match!; 	cpy <MatchTemp+2	bge @MatchGood;; Otherwise we have a certain number of characters left in the string to find...; we must calculate how many...	stx <MatchTemp	; save the current offset into matchstr	lda <MatchTemp+2	; get the length of match string	sec	sbc <MatchTemp	; subtract where we are...	sta <MatchTemp	; matchTemp now cleverly contains	lda <i	; number of chars in inputstr	sec	sbc <MatchTemp	sta <MatchTemp	; save it in match temp	cpy <MatchTemp	; see if this is legal...	blt @MatchFail	; if <Y> is less than then not enough chars	ldy <MatchTemp	; restart the comparison at this point with the new offset	brl @NextChar	; and get the next character	EndP	End